import React, { useEffect, useMemo, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { adminAPI } from '../utils/api';

const AdminDashboard = () => {
  const navigate = useNavigate();
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [overview, setOverview] = useState(null);
  const [leaderboardTab, setLeaderboardTab] = useState('region');

  useEffect(() => {
    const load = async () => {
      try {
        const response = await adminAPI.getOverview();
        setOverview(response.data);
      } catch (err) {
        setError(err.response?.data?.error || 'Failed to load admin analytics.');
      } finally {
        setLoading(false);
      }
    };

    load();
  }, []);

  const boardData = useMemo(() => {
    if (!overview) {
      return [];
    }

    if (leaderboardTab === 'school') {
      return overview.leaderboards.bySchool;
    }

    if (leaderboardTab === 'readers') {
      return overview.topReaders;
    }

    return overview.leaderboards.byRegion;
  }, [overview, leaderboardTab]);

  const handleCsvExport = () => {
    window.open(adminAPI.getCsvReportUrl(), '_blank', 'noopener,noreferrer');
  };

  const handlePdfExport = () => {
    window.open(adminAPI.getPdfReportUrl(), '_blank', 'noopener,noreferrer');
  };

  const handleCertificate = (userId) => {
    window.open(adminAPI.getCertificateUrl(userId), '_blank', 'noopener,noreferrer');
  };

  if (loading) {
    return (
      <div className="loading">
        <div className="spinner"></div>
        <p>Loading admin dashboard...</p>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container">
        <div className="error">{error}</div>
      </div>
    );
  }

  const { metrics, byLanguage, recentBooks } = overview;

  return (
    <div className="dashboard-page admin-page">
      <nav className="site-nav dashboard-nav">
        <div className="brand-lockup">
          <h1>Admin Dashboard</h1>
          <p>Monitoring and reporting center</p>
        </div>
        <div className="nav-actions">
          <button className="btn btn-outline btn-compact" onClick={() => navigate('/')}>
            Home
          </button>
          <button className="btn btn-compact" onClick={() => navigate('/dashboard')}>
            Reader Dashboard
          </button>
        </div>
      </nav>

      <main className="dashboard-shell">
        <section className="dashboard-hero admin-hero animate-rise">
          <div>
            <p className="eyebrow dark">Program Analytics</p>
            <h2>Gift of Reading Control Center</h2>
            <p>
              Track participation, compare performance across regions and schools,
              and generate certificates plus formal reports.
            </p>
          </div>
          <div className="dashboard-profile">
            <span>Campaign Progress</span>
            <strong>{metrics.percentageComplete}%</strong>
          </div>
        </section>

        <section className="dashboard-grid animate-stagger">
          <div className="metric-card">
            <p>Total Books</p>
            <strong>{metrics.totalBooks.toLocaleString()}</strong>
            <span>toward {metrics.target.toLocaleString()}</span>
          </div>
          <div className="metric-card">
            <p>Registered Users</p>
            <strong>{metrics.totalUsers.toLocaleString()}</strong>
            <span>{metrics.activeReaders.toLocaleString()} active readers</span>
          </div>
          <div className="metric-card">
            <p>Coverage</p>
            <strong>{metrics.totalSchools}</strong>
            <span>{metrics.totalRegions} regions</span>
          </div>
        </section>

        <section className="workspace-grid admin-grid">
          <div className="panel-card animate-rise delay-1">
            <div className="panel-heading horizontal">
              <div>
                <p className="eyebrow dark">Leaderboards</p>
                <h3>Top Readers by Group</h3>
              </div>
              <div className="segmented">
                <button
                  className={leaderboardTab === 'region' ? 'segmented-active' : ''}
                  onClick={() => setLeaderboardTab('region')}
                >
                  Region
                </button>
                <button
                  className={leaderboardTab === 'school' ? 'segmented-active' : ''}
                  onClick={() => setLeaderboardTab('school')}
                >
                  School
                </button>
                <button
                  className={leaderboardTab === 'readers' ? 'segmented-active' : ''}
                  onClick={() => setLeaderboardTab('readers')}
                >
                  Readers
                </button>
              </div>
            </div>

            <div className="table-scroll">
              <table className="data-table">
                <thead>
                  {leaderboardTab === 'readers' ? (
                    <tr>
                      <th>#</th>
                      <th>Name</th>
                      <th>School</th>
                      <th>Region</th>
                      <th>Books</th>
                      <th>Certificate</th>
                    </tr>
                  ) : (
                    <tr>
                      <th>#</th>
                      <th>{leaderboardTab === 'region' ? 'Region' : 'School'}</th>
                      <th>Readers</th>
                      <th>Books</th>
                    </tr>
                  )}
                </thead>
                <tbody>
                  {boardData.map((row, index) => (
                    leaderboardTab === 'readers' ? (
                      <tr key={row.id}>
                        <td>{index + 1}</td>
                        <td><strong>{row.firstName} {row.lastName}</strong></td>
                        <td>{row.location}</td>
                        <td>{row.region}</td>
                        <td>{row.booksReadCount}</td>
                        <td>
                          <button className="btn btn-outline btn-compact" onClick={() => handleCertificate(row.id)}>
                            PDF
                          </button>
                        </td>
                      </tr>
                    ) : (
                      <tr key={`${row.name}-${index}`}>
                        <td>{index + 1}</td>
                        <td><strong>{row.name}</strong></td>
                        <td>{row.totalUsers}</td>
                        <td>{row.totalBooks}</td>
                      </tr>
                    )
                  ))}
                </tbody>
              </table>
            </div>
          </div>

          <div className="panel-card animate-rise delay-2">
            <div className="panel-heading">
              <p className="eyebrow dark">Reporting</p>
              <h3>Exports and Language Analysis</h3>
            </div>
            <div className="export-actions">
              <button className="btn" onClick={handleCsvExport}>Export CSV Report</button>
              <button className="btn btn-secondary" onClick={handlePdfExport}>Export PDF Summary</button>
            </div>

            <div className="language-list">
              {byLanguage.map((item) => (
                <div key={item.language} className="language-item">
                  <span>{item.language}</span>
                  <strong>{item.totalBooks}</strong>
                </div>
              ))}
            </div>
          </div>
        </section>

        <section className="panel-card animate-rise delay-3">
          <div className="panel-heading horizontal">
            <div>
              <p className="eyebrow dark">Latest Activity</p>
              <h3>Recent Book Entries</h3>
            </div>
          </div>
          <div className="table-scroll">
            <table className="data-table">
              <thead>
                <tr>
                  <th>Reader</th>
                  <th>Book</th>
                  <th>Author</th>
                  <th>Language</th>
                  <th>School</th>
                  <th>Region</th>
                  <th>Date</th>
                </tr>
              </thead>
              <tbody>
                {recentBooks.map((entry) => (
                  <tr key={entry.id}>
                    <td><strong>{entry.reader}</strong></td>
                    <td>{entry.bookTitle}</td>
                    <td>{entry.author}</td>
                    <td>{entry.language}</td>
                    <td>{entry.school}</td>
                    <td>{entry.region}</td>
                    <td>{new Date(entry.recordedAt).toLocaleDateString('en-US')}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </section>
      </main>
    </div>
  );
};

export default AdminDashboard;
